export const Schema = z.object({
    // prefault：旧聊天存档可能缺失后增的字段，缺了自动补空值，不抛错
    当前主角: z.string().prefault(''),
    当前日期: z.string(),
    角色: z.record(z.string().describe('角色名'), z.object({
        好感度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
        心情: z.enum(['开心', '平静', '想念', '低落', '烦躁']),
        想法: z.string(),
    })),
    共同回忆: z.array(z.object({
        日期: z.string(),
        内容: z.string(),
    })),
    约定事项: z.record(z.string().describe('约定内容简述'), z.object({
        日期: z.string(),
        状态: z.enum(['进行中', '已兑现', '已失效']),
    })),
});
